row := r.conn.QueryRowContext(ctx,
	"SELECT "+selectColumns+" FROM notifications WHERE id = $1", id)

n, err := scanNotification(row)
if errors.Is(err, sql.ErrNoRows) {
	return nil, domain.ErrNotFound
}

result, err := r.conn.ExecContext(ctx, `
	UPDATE notifications
	SET status = $1, attempts = $2, updated_at = $3
	WHERE id = $4`,
	n.Status, n.Attempts, n.UpdatedAt, n.ID,
)

rows, _ := result.RowsAffected()
if rows == 0 {
	return fmt.Errorf("db: %w (id=%s)", domain.ErrNotFound, n.ID)
}

query := "SELECT " + selectColumns + " FROM notifications WHERE 1=1"
var args []any

if filter.Status != "" {
	args = append(args, filter.Status)
	query += fmt.Sprintf(" AND status = $%d", len(args))
}
if filter.Channel != "" {
	args = append(args, filter.Channel)
	query += fmt.Sprintf(" AND channel = $%d", len(args))
}

const pqUniqueViolation = "23505"

_, err = r.conn.ExecContext(ctx, "INSERT INTO notifications (...) VALUES (...)", ...)
if err != nil {
	var pqErr *pq.Error
	if errors.As(err, &pqErr) && pqErr.Code == pqUniqueViolation {
		return domain.ErrDuplicateIdempotencyKey
	}
	return fmt.Errorf("db: falha ao inserir notificação: %w", err)
}

CREATE UNIQUE INDEX IF NOT EXISTS idx_notifications_idempotency_key
    ON notifications (idempotency_key)
    WHERE idempotency_key <> '';

